@@ -0,0 +1,362 @@
+// Copyright 2013 Julien Schmidt. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be found
+// in the LICENSE file.
+
+package router
+
+import (
+	"fmt"
+	"net/http"
+	"reflect"
+	"testing"
+)
+
+func printChildren(n *node, prefix string) {
+	fmt.Printf("%s%s[%d]  %v \r\n", prefix, n.key, len(n.children), n.value)
+	for l := len(n.key); l > 0; l-- {
+		prefix += " "
+	}
+	for _, child := range n.children {
+		printChildren(child, prefix)
+	}
+}
+
+// Used as a workaround since we can't compare functions or their adresses
+var fakeHandlerValue string
+
+func fakeHandler(val string) HandlerFunc {
+	return func(http.ResponseWriter, *http.Request, map[string]string) {
+		fakeHandlerValue = val
+	}
+}
+
+type testRequests []struct {
+	path       string
+	nilHandler bool
+	route      string
+	vars       map[string]string
+}
+
+func checkRequests(t *testing.T, tree *node, requests testRequests) {
+	for _, request := range requests {
+		handler, vars, _ := tree.getValue(request.path)
+
+		if handler == nil {
+			if !request.nilHandler {
+				t.Errorf("Handler mismatch for route '%s': Expected non-nil handler", request.path)
+			}
+		} else if request.nilHandler {
+			t.Errorf("Handler mismatch for route '%s': Expected nil handler", request.path)
+		} else {
+			handler(nil, nil, nil)
+			if fakeHandlerValue != request.route {
+				t.Errorf("Handler mismatch for route '%s': Wrong handler (%s != %s)", request.path, fakeHandlerValue, request.route)
+			}
+		}
+
+		if !reflect.DeepEqual(vars, request.vars) {
+			t.Errorf("Vars mismatch for route '%s'", request.path)
+		}
+	}
+}
+
+func TestTreeAddAndGet(t *testing.T) {
+	tree := &node{}
+
+	routes := [...]string{
+		"/hi",
+		"/contact",
+		"/co",
+		"/c",
+		"/a",
+		"/ab",
+		"/doc/",
+		"/doc/go_faq.html",
+		"/doc/go1.html",
+	}
+	for _, route := range routes {
+		if err := tree.addRoute(route, fakeHandler(route)); err != nil {
+			t.Fatalf("Error inserting route '%s': %s", route, err.Error())
+		}
+	}
+
+	//printChildren(tree, "")
+
+	checkRequests(t, tree, testRequests{
+		{"/a", false, "/a", nil},
+		{"/", true, "", nil},
+		{"/hi", false, "/hi", nil},
+		{"/contact", false, "/contact", nil},
+		{"/co", false, "/co", nil},
+		{"/con", true, "", nil},  // key mismatch
+		{"/cona", true, "", nil}, // key mismatch
+		{"/no", true, "", nil},   // no matching child
+		{"/ab", false, "/ab", nil},
+	})
+}
+
+func TestTreeWildcard(t *testing.T) {
+	tree := &node{}
+
+	routes := [...]string{
+		"/",
+		"/cmd/:tool/:sub",
+		"/cmd/:tool/",
+		"/src/*filepath",
+		"/search/",
+		"/search/:query",
+		"/user_:name",
+		"/user_:name/about",
+		"/doc/",
+		"/doc/go_faq.html",
+		"/doc/go1.html",
+	}
+	for _, route := range routes {
+		if err := tree.addRoute(route, fakeHandler(route)); err != nil {
+			t.Fatalf("Error inserting route '%s': %s", route, err.Error())
+		}
+	}
+
+	//printChildren(tree, "")
+
+	checkRequests(t, tree, testRequests{
+		{"/", false, "/", nil},
+		{"/cmd/test/", false, "/cmd/:tool/", map[string]string{"tool": "test"}},
+		{"/cmd/test", true, "", map[string]string{"tool": "test"}},
+		{"/cmd/test/3", false, "/cmd/:tool/:sub", map[string]string{"tool": "test", "sub": "3"}},
+		{"/src/", true, "", nil},
+		{"/src/some/file.png", false, "/src/*filepath", map[string]string{"filepath": "some/file.png"}},
+		{"/search/", false, "/search/", nil},
+		{"/search/some+cräzy+sh!t", false, "/search/:query", map[string]string{"query": "some+cräzy+sh!t"}},
+		{"/search/some+cräzy+sh!t/", true, "", map[string]string{"query": "some+cräzy+sh!t"}},
+		{"/user_gopher", false, "/user_:name", map[string]string{"name": "gopher"}},
+		{"/user_gopher/about", false, "/user_:name/about", map[string]string{"name": "gopher"}},
+	})
+}
+
+func TestTreeWildcardConflict(t *testing.T) {
+	tree := &node{}
+
+	routes := [...]struct {
+		path     string
+		conflict bool
+	}{
+		{"/cmd/:tool/:sub", false},
+		{"/cmd/vet", true},
+		{"/src/*filepath", false},
+		{"/src/*filepathx", true},
+		{"/search/:query", false},
+		{"/search/invalid", true},
+		{"/user_:name", false},
+		{"/user_x", true},
+		{"/user_:name", false},
+		{"/id:id", false},
+		{"/id/:id", true},
+	}
+	for _, route := range routes {
+		err := tree.addRoute(route.path, nil)
+		if err == ErrWildCardConflict {
+			if !route.conflict {
+				t.Errorf("Unexpected WildcardConflict for route '%s'", route.path)
+			}
+		} else if err != nil {
+			t.Errorf("Unexpected error for route '%s': %v", route.path, err)
+		} else if route.conflict {
+			t.Errorf("No error for conflicting route '%s'", route.path)
+		}
+	}
+
+	//printChildren(tree, "")
+}
+
+func TestTreeChildConflict(t *testing.T) {
+	tree := &node{}
+
+	routes := [...]struct {
+		path     string
+		conflict bool
+	}{
+		{"/cmd/vet", false},
+		{"/cmd/:tool/:sub", true},
+		{"/src/AUTHORS", false},
+		{"/src/*filepath", true},
+		{"/user_x", false},
+		{"/user_:name", true},
+		{"/id/:id", false},
+		{"/id:id", true},
+		{"/:id", true},
+		{"/*filepath", true},
+	}
+	for _, route := range routes {
+		err := tree.addRoute(route.path, nil)
+		if err == ErrChildConflict {
+			if !route.conflict {
+				t.Errorf("Unexpected ErrCatchAllConflict for route '%s'", route.path)
+			}
+		} else if err != nil {
+			t.Errorf("Unexpected error for route '%s': %v", route.path, err)
+		} else if route.conflict {
+			t.Errorf("No error for conflicting route '%s'", route.path)
+		}
+	}
+
+	//printChildren(tree, "")
+}
+
+func TestTreeDupliatePath(t *testing.T) {
+	tree := &node{}
+
+	routes := [...]string{
+		"/",
+		"/doc/",
+		"/src/*filepath",
+		"/search/:query",
+		"/user_:name",
+	}
+	for _, route := range routes {
+		if err := tree.addRoute(route, fakeHandler(route)); err != nil {
+			t.Fatalf("Error inserting route '%s': %s", route, err.Error())
+		}
+
+		// Add again
+		err := tree.addRoute(route, nil)
+		if err == ErrDuplicatePath {
+			// everything is fine
+		} else if err != nil {
+			t.Errorf("Unexpected error for duplicate route '%s': %v", route, err)
+		} else {
+			t.Fatalf("No error for duplicate route '%s", route)
+		}
+	}
+
+	//printChildren(tree, "")
+
+	checkRequests(t, tree, testRequests{
+		{"/", false, "/", nil},
+		{"/doc/", false, "/doc/", nil},
+		{"/src/some/file.png", false, "/src/*filepath", map[string]string{"filepath": "some/file.png"}},
+		{"/search/some+cräzy+sh!t", false, "/search/:query", map[string]string{"query": "some+cräzy+sh!t"}},
+		{"/user_gopher", false, "/user_:name", map[string]string{"name": "gopher"}},
+	})
+}
